/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:visualization:set:usermeta' );


// MAIN //

/**
* Sets optional metadata.
*
* @private
* @param {Object} value - input value
* @throws {TypeError} must be an object
* @returns {void}
*/
function set( value ) {
	if ( !isObject( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be an object. Value: `%s`.', 'usermeta', value ) );
	}
	debug( 'Current value: %s. New value: %s.', JSON.stringify( this._usermeta ), JSON.stringify( value ) );
	this._usermeta = value;
}


// EXPORTS //

module.exports = set;
